if mP and type(nP)==_re[2087]and tonumber(nP.p)~=nil then
return tonumber(nP.p)<0.5
end
local oP,pP=pcall(W.rec,lP.key)
return oP and type(pP)==_re[2087]and(tonumber(pP.streak)or 0)>=2 or false
end
W.MATCHED_DAILY_P=0.7
function W.icWinP(qP)
local rP=qP.rec or W.rec(qP.key)
local sP=W.icLost(qP.room)
local tP=sP and sP.n or 0
local uP=((tonumber(rP.wins)or 0)+(qP.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(rP.runs)or 0)+2)
local vP=W.sim(qP)
local wP,xP=0,0
if vP and tonumber(vP.p)then
local yP=type(vP.trust)==_re[2087]and vP.trust or nil
local zP=yP~=nil and not yP.ok
local AP=zP and(tonumber(yP.ratio)or 1)>1
if not zP or(AP and not vP.won)or(zP and not AP and vP.won)then
local BP,CP=pcall(gb.styleP,vP)
wP,xP=(BP and tonumber(CP))or tonumber(vP.p),W.IC.SIM_W
end
end
return(uP*2+wP*xP)/(tP+2+xP)
end
function W.winP(DP)
if DP.kind==_re[2542]then
return W.icWinP(DP)
end
if DP.kind==_re[2540]and O.dailyMatch and not O.dailyLoop then
local FP,GP=pcall(W.needsHelp,DP)
if FP and GP then
return W.MATCHED_DAILY_P
end
end
local HP=DP.rec
local IP=DP.p0 or W.PRIOR_WIN[DP.kind]or 0.7
local JP=W.sim(DP)
if JP and not(JP.trust and not JP.trust.ok)then
local KP=JP.calibrated or HP.runs>0
local LP=(JP.trust and JP.trust.ok)and 6 or(KP and 3 or 1.5)
local MP=(KP or JP.hopeless)and 0 or 2
local NP,OP=pcall(gb.styleP,JP)
return(HP.wins+IP*MP+(NP and OP or JP.p)*LP)/(HP.runs+MP+LP)
end
return(HP.wins+IP*2)/(HP.runs+2)
end
function W.minutes(PP)
local QP=PP.rec
local RP=tonumber(QP.timed)or 0
local SP=PP.kind==_re[2107]and P.simRes[PP.key]
local TP=(RP>0 and QP.sec>0)and(QP.sec/RP/60)or(SP and tonumber(SP.minutes))or W.PRIOR_MIN[PP.kind]or 6
return TP+W.OVERHEAD
end
function W.score(UP)
local VP,WP=((UP.kind==_re[2105]and UP.rec.runs>0)or UP.kind==_re[2107]or UP.kind==_re[2543])and 1 or(UP.kind==_re[2108]and UP.p0)or W.winP(UP),W.minutes(UP)
local XP,YP,ZP=pcall(kb.modeBonus,UP)
if XP and(YP or 0)>0 then
UP.teamBonus=YP
if not tostring(UP.why):find(_re[2816],1,true)then
UP.why=(UP.why or _re[1006]).._re[2463]..ZP
end
end
local _P=VP*(UP.value+(UP.teamBonus or 0))/WP
UP.baseScore=_P
local aQ,bQ,cQ=pcall(ib.valueFor,UP)
if aQ and bQ>0 then
local dQ=VP*(UP.value+bQ)/(WP*cQ)
if dQ>_P then
_P,UP.train=dQ,bQ
end
end
if UP.rec.runs<2 then
_P=_P*(1+O.exploreBonus)
end
return _P
end
