end
local rQ=hQ.study and P.study and P.study.id==iQ and P.study or nil
if rQ and jQ.collection:get_unit_by_uuid(rQ.uuid)then
kQ=jQ.collection:get_unit_by_uuid(rQ.uuid)
end
if not kQ then
F.log(1,_re[2820],V.name(iQ).._re[2821])
hQ.i=(tonumber(hQ.i)or 1)+1
