end
if uQ then
sQ[uQ]=kQ.uuid
else
table.insert(sQ,kQ.uuid)
end
end
for BQ,CQ in ipairs(rQ and rQ.summoners or{})do
if not table.find(sQ,CQ)and jQ.collection:get_unit_by_uuid(CQ)then
local DQ,EQ
for FQ,GQ in ipairs(sQ)do
local HQ=jQ.collection:get_unit_by_uuid(GQ)
if HQ and GQ~=kQ.uuid and not table.find(rQ.summoners,GQ)and not V.isFarm(HQ.unit_id)and not V.allyBuff(HQ.unit_id)then
local IQ,JQ=pcall(V.score,HQ)
JQ=IQ and JQ or 0
if not EQ or JQ<EQ then
DQ,EQ=FQ,JQ
end
end
end
if DQ then
sQ[DQ]=CQ
