local KR=JR:lower()
local LR={name=tostring(IR.name or HR),text=JR:sub(1,400)}
local MR={}
for NR in KR:gmatch(_re[2870])do
if tonumber(NR)then
table.insert(MR,tonumber(NR))
end
end
if#MR>0 then
LR.pct=MR
end
LR.every=tonumber(KR:match(_re[2871]))or tonumber(KR:match(_re[2872]))or tonumber(KR:match(_re[2873]))
LR.sec=tonumber(KR:match(_re[2874]))
LR.upTo=tonumber(KR:match(_re[2250]))
