function eb.upgradeGain(NBb,OBb,PBb,QBb,RBb,SBb)
local TBb,UBb=OBb[PBb],OBb[PBb+1]
local VBb=(TBb.cd>0 and TBb.damage/TBb.cd or 0)
local WBb=(UBb.cd>0 and UBb.damage/UBb.cd or 0)*V.aoe(UBb.atk,UBb.range)/math.max(0.3,V.aoe(TBb.atk,TBb.range))
local XBb=VBb>0 and NBb*(WBb/VBb-1)or(SBb or 0)
local YBb=OBb[PBb+2]
if YBb and PBb+1<OBb.max and YBb.cd>0 and UBb.cd>0 and VBb>0 then
local ZBb=NBb*((YBb.damage/YBb.cd)/VBb-1)
local _Bb=QBb+YBb.cost*RBb
if ZBb/_Bb>XBb/QBb then
XBb=XBb+(ZBb/_Bb*QBb-XBb)*0.5
end
end
local aCb=(UBb.range or 0)>(TBb.range or 0)and(1+((UBb.range-TBb.range)/math.max(1,TBb.range)))or 1
return math.max(0,XBb)*aCb
end
function eb.dpsFor(bCb,cCb)
if cCb<=0 then
return 0
end
local dCb={}
for eCb,fCb in ipairs(bCb)do
if not fCb.farm and not fCb.grif and fCb.gain>0 then
table.insert(dCb,fCb)
end
end
table.sort(dCb,function(gCb,hCb)
return gCb.gain/gCb.cost>hCb.gain/hCb.cost
end)
local iCb,jCb=0,0
for kCb,lCb in ipairs(dCb)do
if cCb<=0 then
break
end
jCb=lCb.gain/lCb.cost
local mCb=math.min(1,cCb/lCb.cost)
iCb=iCb+lCb.gain*mCb
cCb=cCb-lCb.cost*mCb
end
return iCb+math.max(0,cCb)*jCb*0.7
end
function eb.shieldDps(nCb,oCb,pCb,qCb,rCb,sCb,tCb)
if(qCb or 0)<=0 or(nCb or 0)<=0 or(rCb or 0)<=0 then
return nCb or 0
end
oCb,pCb,sCb=math.max(0.3,oCb or 2),math.max(1,pCb or 1),sCb or 1
local uCb=nCb*sCb*oCb/pCb
return rCb*pCb/((qCb/math.max(1,tCb or 1)+math.max(1,rCb/uCb))*oCb)/sCb
end
function eb.shieldGain(vCb,wCb,xCb,yCb,zCb,ACb,BCb,CCb)
local DCb,ECb=V.attackInfo(wCb.atk,wCb.range),V.attackInfo(yCb.atk,yCb.range)
local FCb=eb.shieldDps(vCb,(tonumber(wCb.cd)or 2)*(BCb or 1),DCb.n,zCb,ACb,CCb,DCb.hits)
local GCb=eb.shieldDps(xCb,(tonumber(yCb.cd)or 2)*(BCb or 1),ECb.n,zCb,ACb,CCb,ECb.hits)
local HCb=math.max(0,((tonumber(yCb.range)or 0)-(tonumber(wCb.range)or 0))/math.max(1,tonumber(wCb.range)or 1))
return math.max(0,GCb-FCb)+FCb*HCb
end
function eb.shieldWork(ICb,JCb,KCb,LCb,MCb,NCb,OCb,PCb,QCb)
if(LCb or 0)<=0 then
return 0
end
local RCb=3*LCb*(MCb or 1)/math.max(1,NCb or 20)
if(KCb or 0)>=RCb then
return 0
end
return math.max(1,ICb or 1)*math.max(1,QCb or 1)/math.max(0.3,JCb or 2)*math.min(OCb or 0,PCb or 0)
end
function eb.holdGain(SCb,TCb,UCb,VCb)
if not SCb or(TCb or 0)<=0 then
return 0
end
local WCb,XCb=tonumber(SCb.stun)or 0,tonumber(SCb.slowTime)or 0
if WCb<=0 and XCb<=0 then
return 0
end
local YCb,ZCb=WCb>0 and WCb or XCb,WCb>0 and 1 or(tonumber(SCb.slowPct)or 0.3)
local _Cb=ZCb*YCb/(YCb+(tonumber(SCb.ccCd)or 8))
local aDb=_Cb/math.max(0.1,1-_Cb)
return TCb*aDb*U.clamp(UCb or 0.5,0,1)*math.min(1,(tonumber(SCb.n)or 1)/2)/(1+(VCb or 0))
