function eb.keepsUp(mDb,nDb,oDb,pDb,qDb)
local rDb=mDb.coming
if not(rDb and#rDb>0 and mDb.waveSec)then
return true
end
local sDb=mDb.eff or 1
local tDb=mDb.money-oDb
local uDb=(mDb.teamDps or 0)*(mDb.shieldK or 1)+(pDb or 0)*sDb+eb.dpsFor(nDb,math.max(0,tDb))*sDb
local vDb=(mDb.farmNow or 0)+(qDb or 0)
local wDb=(mDb.roadSec or 130)*U.clamp(mDb.cover or 0.6,0.1,1)
local xDb=mDb.hpAlive or 0
for yDb,zDb in ipairs(rDb)do
xDb=math.max(0,xDb+zDb.hp-uDb*mDb.waveSec)
local ADb=uDb*wDb
if xDb>ADb then
return false,yDb,ADb/math.max(1,xDb)
end
if yDb< #rDb then
uDb=uDb+eb.dpsFor(nDb,(zDb.reward or 0)+vDb)*sDb*(0.85^yDb)
end
end
return true
end
function eb.decide(BDb,CDb)
local DDb=U.clamp(CDb.cover or 0.6,0.1,1)
