table.insert(Bkc,tostring(jb.item(Ekc.id).name or Ekc.id))
if not Ekc.bought and not jb.isCurse(Ekc.id)then
Ekc.luck=tonumber(jb.item(Ekc.id).luck_increase)~=nil
Ekc.v=jb.itemValue(Ekc.id,ukc)
if not Ekc.luck and Ekc.v/math.max(1,Ekc.cost)<jb.MIN_WORTH then
Ckc=Ckc+1
