local fqc=0
for gqc=2,#aqc do
local hqc,iqc=aqc[gqc-1],aqc[gqc]
local jqc=(iqc-hqc).Magnitude
local kqc=math.max(1,math.floor(jqc/2))
for lqc=0,kqc-1 do
local mqc=hqc:Lerp(iqc,lqc/kqc)
table.insert(bb.samples,{pos=mqc,prog=(fqc+jqc*lqc/kqc)/math.max(1,dqc),lane=Zpc.Name})
end
fqc=fqc+jqc
end
if aqc[#aqc]then
table.insert(bb.samples,{pos=aqc[#aqc],prog=1,lane=Zpc.Name})
end
end
end
