table.insert(Nuc,{p=U.flat(Puc:GetPivot().Position),r=Quc.range.Value*(V.SUMMONER[Quc.id.Value]and V.SUMMONER[Quc.id.Value].reach or 1),air=bb.canAir(Puc)})
