if Uuc.prog>Suc then
local Vuc=U.flat(Uuc.pos)
for Wuc,Xuc in ipairs(Nuc)do
if(Vuc-Xuc.p).Magnitude<=Xuc.r then
if Uuc.prog>Ruc then
