end
end
end
local tvc= #Nuc>0 and(bb.pressure or 0)>=Ruc-0.08
return{covEnd=Ruc,airEnd=Suc,leak=mvc,leakLane=ovc,covL=Yuc,airLeak=nvc,push=tvc,units= #Nuc}
