local cid,did=0,0
local eid,fid=Xhd.foes or{},Yhd.foes or{}
for gid,hid in pairs(fid)do
if hid.prog>=bb.BASE_END then
cid=cid+hid.hp
local iid=eid[gid]
if iid then
did=did+math.max(0,iid.hp-hid.hp)
end
end
end
